// ALL ATTEMPT-18 PARAMETERS PRESERVED:
//   - prefixBudget = maxSteps - 100 (force-open at step 800)
//   - maxSpanTokens = 22 (prevents runaway constrained generation)
//   - nearBudgetThreshold = 30 (CloseSpanWithinBudget when budget <= 30)
//   - penaltyTokens = ["{", "}", "**", "^", "\\"] at penalty 8.0
//   - break after first clean span close
//   - EOS inside span → CloseSpanWithinBudget with remaining budget
//   - AdaptiveConstrainedStepWithPenalties for hard parser control
//   - RenderedEndsWith for delimiter detection (required API)
//   - minPreludeSteps = 50 (guards against early task-description echoes)
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1: parser_validity
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Branch A (outside span, UnconstrainedStep, non-EOS, no << or steps < minPrelude):
//   insideConstrainedOut stays false. Implication vacuously true.
//
// Branch B (outside span, UnconstrainedStep, non-EOS, RenderedEndsWith=true, steps >= 50):
//   generated := generated + [next]; EnterObservedConstrainedSpan sets
//   insideConstrainedOut := true, currentConstrainedOut := [].
//   parser.IsValidPrefix([]) holds by precondition. Preserved.
//
// Branch C (outside span, EOS):
//   insideConstrainedOut stays false. Implication vacuously true.
//
// Branch D (outside span, force-open at prefixBudget, remainingBudget > 5):
//   OpenConstrainedSpan appends "<<", sets insideConstrainedOut := true,
//   currentConstrainedOut := []. parser.IsValidPrefix([]) by precondition. Preserved.
//
// Branch E (inside span, nearBudget <= 30 or spanTokens >= 22):
//   CloseSpanWithinBudget postcondition guarantees
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut). Preserved.
//
// Branch F (inside span, CloseSpanIfComplete closed=true):
//   insideConstrainedOut set false; implication vacuously true. Preserved.
//
// Branch G (inside span, CloseSpanIfComplete closed=false, next != EOS):
//   AdaptiveConstrainedStepWithPenalties hard-masks to parser-valid tokens plus EOS
//   and returns a parser-valid next token by contract. AppendConstrainedToken appends
//   next to currentConstrainedOut, preserving parser.IsValidPrefix. Preserved.
//
// Branch H (inside span, EOS from AdaptiveConstrained):
//   CloseSpanWithinBudget postcondition guarantees validity. Preserved.
//
// Invariant 2: |generated| <= |generatedPrefix| + steps
//
// Branch A (UnconstrainedStep non-EOS, no span entry):
//   generated += [next] (+1), steps += 1. Preserved.
// Branch B (UnconstrainedStep, RenderedEndsWith true, steps >= 50):
//   generated += [next] (+1), steps += 1. EnterObservedConstrainedSpan: +0 cost, no append. Preserved.
// Branch C (EOS in unconstrained): steps += 1, no append. Preserved.
// Branch D (OpenConstrainedSpan): appends exactly 1 token, steps += 1. Preserved.
// Branch E (CloseSpanWithinBudget, near budget or spanTokens >= max):
//   closeBudget = remainingBudget = maxSteps - steps_before.
//   |generated| grows by at most closeBudget; steps grows by closeBudget to maxSteps.
//   |generated| <= |gP| + maxSteps. Preserved.
// Branch F (CloseSpanIfComplete closed=true): at most 1 ">>" appended, steps += 1. Preserved.
// Branch G (CloseSpanIfComplete closed=false, Adaptive + AppendConstrainedToken):
//   CloseSpanIfComplete: steps += 1, no visible append when closed=false.
//   AppendConstrainedToken: 0 cost, appends 1 token to generated.
//   Net: |generated| grows by 1, steps grows by 1. Preserved.
// Branch H (EOS inside span, CloseSpanWithinBudget):
//   rem = maxSteps - steps; steps grows by rem to maxSteps.
//   |generated| grows by at most rem. Preserved.
// CSD_PROOF_SKETCH_END

